import { OlapTable, Stream, IngestApi, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Product Event Data Model
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: string; // "view", "cart", "purchase"
  properties: Record<string, any>; // JSON object for flexible properties like price, page, etc.
}

// INGEST PIPELINE - The explicit trio: OlapTable + Stream + IngestApi

// ClickHouse table - the persistent store
export const ProductEventTable = new OlapTable<ProductEvent>("ProductEvent", {
  orderByFields: ["event_ts", "user_id", "product_id"],
});

// Redpanda topic - buffer between ingest and table
export const ProductEventStream = new Stream<ProductEvent>("ProductEvent", {
  destination: ProductEventTable,
});

// HTTP ingest endpoint - POST /ingest/ProductEvent
export const ProductEventIngest = new IngestApi<ProductEvent>("ProductEvent", {
  destination: ProductEventStream,
});

// MATERIALIZED VIEWS FOR PRE-AGGREGATIONS

// 1. Top Products View - view/cart/purchase counts and revenue
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  revenue: number;
}

export const TopProductsMV = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["revenue", "purchase_count", "product_id"],
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(toFloat64OrZero(JSONExtractString(properties, 'price')), event_type = 'purchase') AS revenue
    FROM ${ProductEventTable}
    GROUP BY product_id
  `,
  selectTables: [ProductEventTable],
});

// 2. Conversion Funnel View - views → carts → purchases with unique users and totals
interface ConversionFunnelRow {
  step: string;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnelMV = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step"],
  selectStatement: sql.statement`
    SELECT
      step,
      uniq(user_id) AS unique_users,
      count() AS total_events
    FROM (
      SELECT user_id, 'view' AS step FROM ${ProductEventTable} WHERE event_type = 'view'
      UNION ALL
      SELECT user_id, 'cart' AS step FROM ${ProductEventTable} WHERE event_type = 'cart'
      UNION ALL
      SELECT user_id, 'purchase' AS step FROM ${ProductEventTable} WHERE event_type = 'purchase'
    )
    GROUP BY step
  `,
  selectTables: [ProductEventTable],
});

// 3. Hourly Activity View - event counts per hour per event type
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
}

export const HourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ${ProductEventTable}
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventTable],
});

// EGRESS APIs FOR ANALYTICS

// API 1: Top Products (with optional limit parameter)
interface TopProductsParams {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsParams, TopProductsRow[]>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const query = sql.statement`
      SELECT product_id, view_count, cart_count, purchase_count, revenue
      FROM ${TopProductsMV.targetTable}
      ORDER BY revenue DESC, purchase_count DESC
      LIMIT ${limit}
    `;
    const data = await client.query.execute<TopProductsRow>(query);
    return await data.json();
  }
);

// API 2: Conversion Funnel
interface ConversionFunnelParams {}

export const conversionFunnelApi = new Api<ConversionFunnelParams, ConversionFunnelRow[]>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const query = sql.statement`
      SELECT step, unique_users, total_events
      FROM ${ConversionFunnelMV.targetTable}
      ORDER BY
        CASE
          WHEN step = 'view' THEN 1
          WHEN step = 'cart' THEN 2
          WHEN step = 'purchase' THEN 3
          ELSE 4
        END
    `;
    const data = await client.query.execute<ConversionFunnelRow>(query);
    return await data.json();
  }
);

// API 3: Hourly Activity (with optional time range)
interface HourlyActivityParams {
  hours_back?: number;
}

export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityRow[]>(
  "hourly-activity",
  async ({ hours_back = 24 }, { client, sql }) => {
    const query = sql.statement`
      SELECT hour, event_type, event_count
      FROM ${HourlyActivityMV.targetTable}
      WHERE hour >= now() - INTERVAL ${hours_back} HOUR
      ORDER BY hour DESC, event_type
    `;
    const data = await client.query.execute<HourlyActivityRow>(query);
    return await data.json();
  }
);

