const express = require('express');
const { execSync } = require('child_process');

const app = express();
const port = 3000;

// Helper function to run ClickHouse queries via moose CLI
function queryClickHouse(sql) {
  try {
    const result = execSync(`moose query "${sql.replace(/"/g, '\\"')}"`, {
      cwd: '/workspace/moose-project',
      encoding: 'utf8'
    });

    // Parse the JSON output from moose query
    const lines = result.trim().split('\n');
    const jsonLines = lines.filter(line => line.startsWith('{'));
    return jsonLines.map(line => JSON.parse(line));
  } catch (error) {
    console.error('Query error:', error);
    throw new Error('Database query failed');
  }
}

// Top Products API
app.get('/top-products', (req, res) => {
  const limit = parseInt(req.query.limit) || 10;

  try {
    const results = queryClickHouse(`
      SELECT product_id, view_count, cart_count, purchase_count, revenue
      FROM TopProducts
      ORDER BY revenue DESC, purchase_count DESC
      LIMIT ${limit}
    `);

    res.json(results);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Conversion Funnel API
app.get('/conversion-funnel', (req, res) => {
  try {
    const results = queryClickHouse(`
      SELECT step, unique_users, total_events
      FROM ConversionFunnel
      ORDER BY
        CASE
          WHEN step = 'view' THEN 1
          WHEN step = 'cart' THEN 2
          WHEN step = 'purchase' THEN 3
          ELSE 4
        END
    `);

    res.json(results);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Hourly Activity API
app.get('/hourly-activity', (req, res) => {
  const hoursBack = parseInt(req.query.hours_back) || 24;

  try {
    const results = queryClickHouse(`
      SELECT hour, event_type, event_count
      FROM HourlyActivity
      WHERE hour >= now() - INTERVAL ${hoursBack} HOUR
      ORDER BY hour DESC, event_type
    `);

    res.json(results);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date() });
});

// Start server
app.listen(port, () => {
  console.log(`Analytics API server running at http://localhost:${port}`);
  console.log('Available endpoints:');
  console.log('  GET /top-products?limit=N');
  console.log('  GET /conversion-funnel');
  console.log('  GET /hourly-activity?hours_back=N');
  console.log('  GET /health');
});

