// Ingest endpoint for new events
app.post('/ingest/ProductEvent', (req, res) => {
  try {
    const event = req.body;

    // Validate required fields
    const required = ['event_id', 'event_ts', 'user_id', 'product_id', 'event_type', 'properties'];
    for (const field of required) {
      if (!event[field]) {
        return res.status(400).json({ error: `Missing required field: ${field}` });
      }
    }

    // Format timestamp for ClickHouse
    const timestamp = event.event_ts.replace('T', ' ').replace('Z', '');
    const properties = JSON.stringify(event.properties).replace(/'/g, "\\'");

    // Insert into ClickHouse
    const sql = `INSERT INTO ProductEvent (event_id, event_ts, user_id, product_id, event_type, properties) VALUES ('${event.event_id}', '${timestamp}', '${event.user_id}', '${event.product_id}', '${event.event_type}', '${properties}')`;

    queryClickHouse(sql);

    res.json({ status: 'success', message: 'Event ingested successfully' });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date() });
});

